import pandas as pd

def longest_team_pass_streak(teams: pd.DataFrame, passes: pd.DataFrame) -> pd.DataFrame:
    merged = passes.merge(teams, left_on='pass_from', right_on='player_id').rename(columns={'team_name': 'team1'})
    merged = merged.merge(teams, left_on='pass_to', right_on='player_id').rename(columns={'team_name': 'team2'})
    merged = merged.sort_values(['team1', 'time_stamp'])

    records = []
    for team1, group in merged.groupby('team1'):
        max_streak = 0
        curr_streak = 0
        for _, row in group.iterrows():
            if row['team1'] == row['team2']:
                curr_streak += 1
                if curr_streak > max_streak:
                    max_streak = curr_streak
            else:
                curr_streak = 0
        if max_streak > 0:
            records.append({'team_name': team1, 'longest_streak': max_streak})

    res = pd.DataFrame(records)
    if res.empty:
        return pd.DataFrame(columns=['team_name', 'longest_streak'])
    return res.sort_values('team_name')
